const clientes = $json.body.clientes;

return clientes.map(cliente => ({
  json: cliente
}));

const itens = $input.all();

const clientes = itens.filter(item => item.json.nome);
const csvItem = itens.find(item => item.json.data);

const linhas = csvItem.json.data.trim().split("\n");

const investimentos = linhas.slice(1).map(linha => {
  const [perfil, produto, minimo, rentabilidade] = linha.split(",");

  return {
    perfil,
    produto,
    minimo: Number(minimo),
    rentabilidade
  };
});

return clientes.map(item => {
  const cliente = item.json;

  const saldo = Number(
    cliente.saldo
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );

  const opcoes = investimentos.filter(
    investimento =>
      investimento.perfil === cliente.perfil &&
      investimento.minimo <= saldo
  );

  const investimento = opcoes[0];

  return {
    json: {
      ...cliente,
      saldoNumerico: saldo,
      produto: investimento ? investimento.produto : "Nenhuma opção disponível",
      minimo: investimento ? investimento.minimo : null,
      rentabilidade: investimento ? investimento.rentabilidade : null
    }
  };
});

return $input.all().map(item => {
  const cliente = item.json;

  let mensagem;

  if (cliente.perfil === "Conservador") {
    mensagem = `Olá, ${cliente.nome}! Com base no seu perfil Conservador, recomendamos ${cliente.produto}, uma opção focada em segurança e estabilidade.`;
  } 
  else if (cliente.perfil === "Moderado") {
    mensagem = `Olá, ${cliente.nome}! Com base no seu perfil Moderado, recomendamos ${cliente.produto}, buscando um equilíbrio entre segurança e potencial de rentabilidade.`;
  } 
  else if (cliente.perfil === "Arrojado") {
    mensagem = `Olá, ${cliente.nome}! Com base no seu perfil Arrojado, recomendamos ${cliente.produto}, uma opção com maior potencial de retorno e também maior exposição a riscos.`;
  } 
  else {
    mensagem = `Olá, ${cliente.nome}! Não encontramos uma recomendação adequada para o seu perfil.`;
  }

  return {
    json: {
      ...cliente,
      mensagem
    }
  };
});
